<?php
 declare(strict_types=1); require __DIR__.'/../config/config.php'; require_role(['pharmacist','manager','admin']);
function h($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
function importRows(string $path,string $ext):array{if($ext==='csv'){$fh=fopen($path,'rb');if(!$fh)throw new RuntimeException('Unable to read CSV.');$headers=fgetcsv($fh);if(!$headers)throw new RuntimeException('CSV is empty.');$headers=array_map(fn($x)=>strtolower(trim((string)$x)),$headers);$rows=[];while(($r=fgetcsv($fh))!==false){if(count(array_filter($r,fn($x)=>trim((string)$x)!==''))===0)continue;$row=[];foreach($headers as $i=>$key)$row[$key]=trim((string)($r[$i]??''));$rows[]=$row;}fclose($fh);return $rows;}throw new RuntimeException('Use CSV import for medicine catalogue.');}
$columns=['name','generic_name','strength','manufacturer','barcode','unit_name','units_per_strip','strips_per_box','purchase_price','retail_unit_price','reorder_level','min_profit_margin_pct'];
if(isset($_GET['download_template'])){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename=medicines_template.csv');$fh=fopen('php://output','wb');fputcsv($fh,$columns);fputcsv($fh,['Demo Paracetamol','Paracetamol','500mg','Demo Manufacturer','100000000001','tablet',10,10,4,5,20,10]);fclose($fh);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$pdo=db();try{$action=$_POST['action']??'bulk_save';if($action==='bulk_save'){$rows=json_decode($_POST['rows']??'[]',true)?:[];if(!$rows)throw new RuntimeException('Add at least one medicine.');$pdo->beginTransaction();$insert=$pdo->prepare('INSERT INTO medicines(name,generic_name,strength,manufacturer,barcode,unit_name,units_per_strip,strips_per_box,purchase_price,retail_unit_price,reorder_level,min_profit_margin_pct) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$n=0;foreach($rows as $r){$name=trim((string)($r['name']??''));if($name==='')continue;$barcode=trim((string)($r['barcode']??''));if($barcode!==''){$q=$pdo->prepare('SELECT id FROM medicines WHERE barcode=?');$q->execute([$barcode]);if($q->fetch())throw new RuntimeException('Barcode already exists: '.$barcode);}$insert->execute([$name,trim((string)($r['generic_name']??''))?:null,trim((string)($r['strength']??''))?:null,trim((string)($r['manufacturer']??''))?:null,$barcode?:null,trim((string)($r['unit_name']??'tablet'))?:'tablet',max(1,(int)($r['units_per_strip']??1)),max(1,(int)($r['strips_per_box']??1)),max(0,(float)($r['purchase_price']??0)),max(0,(float)($r['retail_unit_price']??0)),max(0,(int)($r['reorder_level']??0)),min(100,max(0,(float)($r['min_profit_margin_pct']??10)))]);$n++;}$pdo->commit();audit_log('bulk_medicines_created',$n.' medicines created');header('Location: medicines.php?saved='.$n);exit;}if($action==='import'){if(empty($_FILES['file']['tmp_name']))throw new RuntimeException('Choose a CSV file.');$rows=importRows($_FILES['file']['tmp_name'],strtolower(pathinfo($_FILES['file']['name'],PATHINFO_EXTENSION)));if(!$rows)throw new RuntimeException('No data rows found.');$pdo->beginTransaction();$insert=$pdo->prepare('INSERT INTO medicines(name,generic_name,strength,manufacturer,barcode,unit_name,units_per_strip,strips_per_box,purchase_price,retail_unit_price,reorder_level,min_profit_margin_pct) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$n=0;foreach($rows as $r){$name=trim((string)($r['name']??''));if($name==='')continue;$barcode=trim((string)($r['barcode']??''));if($barcode!==''){$q=$pdo->prepare('SELECT id FROM medicines WHERE barcode=?');$q->execute([$barcode]);if($q->fetch())continue;}$insert->execute([$name,trim((string)($r['generic_name']??''))?:null,trim((string)($r['strength']??''))?:null,trim((string)($r['manufacturer']??''))?:null,$barcode?:null,trim((string)($r['unit_name']??'tablet'))?:'tablet',max(1,(int)($r['units_per_strip']??1)),max(1,(int)($r['strips_per_box']??1)),max(0,(float)($r['purchase_price']??0)),max(0,(float)($r['retail_unit_price']??0)),max(0,(int)($r['reorder_level']??0)),min(100,max(0,(float)($r['min_profit_margin_pct']??10)))]);$n++;}$pdo->commit();header('Location: medicines.php?imported='.$n);exit;}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$rows=db()->query('SELECT m.*,COALESCE(SUM(b.units_remaining),0) stock FROM medicines m LEFT JOIN batches b ON b.medicine_id=m.id WHERE m.active=1 GROUP BY m.id ORDER BY m.name')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Medicines</title><link rel="stylesheet" href="style.css"><style>.bulk{overflow:auto}.bulk table{min-width:1050px}.bulk input{width:100%;box-sizing:border-box;padding:8px;border:1px solid #cbd5e1;border-radius:6px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}.remove{border:0;background:none;color:#dc2626;font-size:20px;cursor:pointer}.hint{font-size:12px;color:#64748b}</style></head><body><header><div class="brand">💊 <?=h(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a class="active" href="manage.php">Management</a></nav><div class="user-info">👤 <?=h(current_user()['username']??'')?> · <a href="logout.php">Logout</a></div></header><main><div class="page-title"><div><div class="eyebrow">CATALOGUE</div><h1>💊 Add Medicines</h1><p>Simple Excel-style entry. Enter the important details first; the rest can stay at their defaults.</p></div></div><?php if($error):?><div class="error">✕ <?=h($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="success">✓ <?=h($_GET['saved'])?> medicines saved.</div><?php endif;?><?php if(isset($_GET['imported'])):?><div class="success">✓ <?=h($_GET['imported'])?> medicines imported.</div><?php endif;?><section class="panel"><h2>➕ Quick Add Medicines</h2><p class="hint">Main fields: Name, Generic, Strength, Barcode, Tabs/Strip, Strips/Box, Purchase and Retail price. Manufacturer and reorder settings are optional.</p><div class="bulk"><table><thead><tr><th>Medicine *</th><th>Generic</th><th>Strength</th><th>Barcode</th><th>Tabs/Strip</th><th>Strips/Box</th><th>Purchase/Tab</th><th>Retail/Tab *</th><th>Manufacturer</th><th>Reorder</th><th></th></tr></thead><tbody id="new"></tbody></table></div><div class="actions"><button type="button" class="btn" id="add">＋ Add Row</button><button type="button" class="btn" id="save">💾 Save All Medicines</button></div></section><section class="panel"><h2>📊 CSV Import</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="import"><input type="file" name="file" accept=".csv" required><button class="btn">⬆ Import CSV</button></form><p class="hint">Required: name. Other supported columns: generic_name, strength, manufacturer, barcode, unit_name, units_per_strip, strips_per_box, purchase_price, retail_unit_price, reorder_level, min_profit_margin_pct.</p><a href="medicines.php?download_template=1">Download CSV template</a></section><section class="panel"><h2>Current Medicines (<?=count($rows)?>)</h2><div class="bulk"><table><tr><th>Medicine</th><th>Pack</th><th>Retail/Tab</th><th>Stock</th></tr><?php foreach($rows as $r):?><tr><td><b><?=h($r['name'])?></b><small><?=h($r['generic_name'])?> <?=h($r['strength'])?></small></td><td><?=$r['units_per_strip']?> tabs/strip × <?=$r['strips_per_box']?> strips/box</td><td>Rs. <?=money($r['retail_unit_price'])?></td><td><?=number_format((int)$r['stock'])?> tabs</td></tr><?php endforeach;?></table></div></section></main><script>const body=document.getElementById('new');function row(){const tr=document.createElement('tr');tr.innerHTML='<td><input data-k="name" placeholder="Panadol 500mg"></td><td><input data-k="generic_name" placeholder="Paracetamol"></td><td><input data-k="strength" placeholder="500mg"></td><td><input data-k="barcode" placeholder="Optional"></td><td><input data-k="units_per_strip" type="number" min="1" value="10"></td><td><input data-k="strips_per_box" type="number" min="1" value="10"></td><td><input data-k="purchase_price" type="number" min="0" step="0.01" value="0"></td><td><input data-k="retail_unit_price" type="number" min="0" step="0.01" value="0"></td><td><input data-k="manufacturer" placeholder="Optional"></td><td><input data-k="reorder_level" type="number" min="0" value="0"></td><td><button type="button" class="remove" onclick="this.closest(\'tr\').remove()">×</button></td>';body.appendChild(tr)}document.getElementById('add').onclick=row;document.getElementById('save').onclick=()=>{const rows=[...body.children].map(tr=>{const o={};tr.querySelectorAll('[data-k]').forEach(x=>o[x.dataset.k]=x.value);return o}).filter(x=>x.name.trim());if(!rows.length)return alert('Add at least one medicine.');const f=document.createElement('form');f.method='post';f.innerHTML='<input name="action" value="bulk_save"><input name="rows">';f.querySelector('[name=rows]').value=JSON.stringify(rows);document.body.appendChild(f);f.submit()};row();row();</script></body></html>